// Phase P1: surprise candidates. A number is surprising when it sits far from what is usual for its class:
//   score = |ln(value / class median)| + a bonus where people tend to guess wrong (the research's myth directions, R-A5).
// (P5 adds the owner's own local guess errors.) Class medians come from story/class-stats.json, generated by
// story/class-stats.gen.test.ts over the whole database; a full-tier test fails when the file is stale.
// Each candidate carries a guess question with three readable options: the truth and the truth ×⅓ / ×3 (or ×2, ×½),
// clamped, rounded to readable steps, never two options within 15% of each other; the truth's place comes from a seed.
import stats from './class-stats.json';
import type { StoryClass, StoryNumber, Surprise } from './types';

export type ClassStats = { v: 1; profile: string; items: number; medians: Record<string, Record<string, number>> };
export const CLASS_STATS = stats as ClassStats;

/** The numbers surprises are drawn from (and that class-stats.json holds medians of). */
export const SURPRISE_KEYS = ['kcal', 'sugarG', 'caffeineMg', 'caffeineAtBedMg', 'alcoholG', 'alcoholGoneMin', 'sugarPeak', 'proteinG', 'fiberG', 'satFatG', 'sodiumMg', 'energyDensity', 'stomachHalfMin', 'waterMl'] as const;
export type SurpriseKey = typeof SURPRISE_KEYS[number];

/** Below these a number is too small to be a story ("1 mg of sodium" is not a surprise, it is nothing). */
export const MIN_VALUE: Record<SurpriseKey, number> = { kcal: 20, sugarG: 2, caffeineMg: 10, caffeineAtBedMg: 5, alcoholG: 1, alcoholGoneMin: 30, sugarPeak: 0.3, proteinG: 3, fiberG: 2, satFatG: 1, sodiumMg: 100, energyDensity: 0.2, stomachHalfMin: 5, waterMl: 100 };
/** At most this many candidates per story (the best first). */
export const MAX_SURPRISES = 6;

/** Myth directions (R-A5): where the usual guess is off, the number gets a bonus. */
const BONUS: Partial<Record<StoryClass | 'all', Partial<Record<SurpriseKey, number>>>> = {
  all: { caffeineAtBedMg: 0.7, alcoholGoneMin: 0.7 }, // "coffee at 5 pm is fine", "coffee sobers you up"
  starch: { sugarPeak: 0.5 }, // "not sweet, so no sugar spike"
  sugar: { sugarG: 0.3 }, // "juice = fruit"
  drink: { kcal: 0.3, sugarG: 0.3 }, // calories you drink go unnoticed
  fat: { satFatG: 0.2 },
  meal: { sodiumMg: 0.3 },
};

const r1 = (x: number) => Math.round(x * 10) / 10;
/** Readable steps: 1 decimal under 3, whole under 20, 5s under 100, 10s under 1000, else 50s. */
export function readable(x: number, decimals = false): number {
  if (decimals && x < 3) return r1(x);
  if (x < 20) return Math.max(1, Math.round(x));
  if (x < 100) return Math.round(x / 5) * 5;
  if (x < 1000) return Math.round(x / 10) * 10;
  return Math.round(x / 50) * 50;
}

interface Form { claim: (n: StoryNumber, N: Record<string, StoryNumber>, ctx: Ctx) => string; question: (ctx: Ctx) => string; value?: (n: StoryNumber) => number; fmt: (v: number) => string; decimals?: boolean; max?: number }
interface Ctx { bed: string; name: string; unit: 'mmol/L' | 'mg/dL' }
const FORMS: Record<SurpriseKey, Form> = {
  kcal: { claim: (n, N) => `${n.text}: ${N.kcalPct?.text ?? ''} of a 2,000 kcal day`, question: () => 'Guess: how many kcal?', fmt: (v) => `${v} kcal` },
  sugarG: { claim: (n) => `${n.text} of sugar${n.anchor ? ` ${n.anchor}` : ''}`, question: () => 'Guess: how much sugar?', fmt: (v) => `${v} g` },
  caffeineMg: { claim: (n) => `${n.text} of caffeine${n.anchor ? ` ${n.anchor}` : ''}`, question: () => 'Guess: how much caffeine?', fmt: (v) => `${v} mg` },
  caffeineAtBedMg: { claim: (n, _N, c) => `${n.text} of caffeine still in you at ${c.bed}`, question: (c) => `Guess: how much caffeine is left at ${c.bed}?`, fmt: (v) => `${v} mg` },
  alcoholG: { claim: (n) => `${n.text} of pure alcohol${n.anchor ? ` ${n.anchor}` : ''}`, question: () => 'Guess: how much pure alcohol?', fmt: (v) => `${v} g` },
  alcoholGoneMin: { claim: (n) => `About ${n.text} until the alcohol is gone (typical body)`, question: () => 'Guess: how long until the alcohol is gone?', value: (n) => Math.round(n.value / 30) / 2, fmt: (v) => `${v} h`, decimals: true, max: 48 },
  sugarPeak: { claim: (n) => `Blood sugar up ${n.text} in a typical body`, question: () => 'Guess: how far does blood sugar rise?', fmt: (v) => `+${v} mmol/L`, decimals: true, max: 5 },
  proteinG: { claim: (n, N) => `${n.text} of protein: ${N.proteinDv?.value ?? 0}% of the Daily Value`, question: () => 'Guess: how much protein?', fmt: (v) => `${v} g` },
  fiberG: { claim: (n, N) => `${n.text} of fiber: ${N.fiberDv?.value ?? 0}% of the Daily Value`, question: () => 'Guess: how much fiber?', fmt: (v) => `${v} g` },
  satFatG: { claim: (n, N) => `${n.text} of saturated fat: ${N.satFatDv?.value ?? 0}% of the Daily Value`, question: () => 'Guess: how much saturated fat?', fmt: (v) => `${v} g` },
  sodiumMg: { claim: (n, N) => `${n.text} of sodium: ${N.sodiumDv?.value ?? 0}% of the Daily Value`, question: () => 'Guess: how much sodium?', fmt: (v) => `${v} mg` },
  energyDensity: { claim: (n) => `${Math.round(n.value * 100)} kcal in every 100 g`, question: () => 'Guess: how many kcal in 100 g?', value: (n) => Math.round(n.value * 100), fmt: (v) => `${v} kcal`, max: 900 },
  stomachHalfMin: { claim: (n) => `Half of it has left your stomach after about ${n.text}`, question: () => 'Guess: when has half left your stomach?', fmt: (v) => `${v} min` },
  waterMl: { claim: (n) => `${n.text} of water${n.anchor ? ` ${n.anchor}` : ''}`, question: () => 'Guess: how much water does it bring?', fmt: (v) => `${v} ml` },
};

/** Three options in ascending order with the truth at `answer`, or null when they cannot be told apart. */
export function guessOptions(truth: number, seed: number, decimals = false, max = Infinity): { opts: [number, number, number]; answer: 0 | 1 | 2 } | null {
  if (!(truth > 0) || !Number.isFinite(truth)) return null;
  const sets: [number[], 0 | 1 | 2][] = [[[1 / 3, 1, 3], 1], [[1, 2, 3], 0], [[1 / 3, 1 / 2, 1], 2]];
  const first = Math.abs(Math.floor(seed)) % 3;
  for (const k of [first, 0, 1, 2]) {
    const [mult, answer] = sets[k];
    const opts = mult.map((m) => (m === 1 ? truth : Math.min(max, readable(truth * m, decimals)))) as [number, number, number];
    const ok = opts.every((v) => v > 0) && opts[0] < opts[1] && opts[1] < opts[2] && opts[1] >= 1.15 * opts[0] && opts[2] >= 1.15 * opts[1];
    if (ok) return { opts, answer };
  }
  return null;
}

/** The surprise candidates of a story, highest score first. */
export function surprisesOf(N: Record<string, StoryNumber>, cls: StoryClass, seed: number, ctx: Ctx): Surprise[] {
  const med = CLASS_STATS.medians[cls] ?? {}, all = CLASS_STATS.medians.all ?? {};
  const out: Surprise[] = [];
  for (const key of SURPRISE_KEYS) {
    const num = N[key];
    if (!num || !(num.value >= MIN_VALUE[key]) || !num.itemSpecific) continue;
    const f0 = FORMS[key];
    // (the sugar rise in the unit picked in "Your body")
    const f: Form = key === 'sugarPeak' && ctx.unit === 'mg/dL' ? { ...f0, value: (x) => Math.round(x.value * 18.016), fmt: (v) => `+${v} mg/dL`, decimals: false, max: 90 } : f0;
    const m = med[key] ?? all[key];
    if (!m || !(m > 0)) continue;
    const score = Math.abs(Math.log(num.value / m)) + (BONUS.all?.[key] ?? 0) + (BONUS[cls]?.[key] ?? 0);
    const truth = f.value ? f.value(num) : f.decimals ? r1(num.value) : Math.round(num.value);
    const g = guessOptions(truth, seed + key.length * 7, !!f.decimals, f.max);
    if (!g) continue;
    out.push({ numberKey: key, claim: f.claim(num, N, ctx), ...(num.anchor ? { anchor: num.anchor } : {}), score: Math.round(score * 1000) / 1000,
      question: f.question(ctx), options: g.opts.map(f.fmt) as [string, string, string], answer: g.answer });
  }
  return out.sort((a, b) => b.score - a.score || a.numberKey.localeCompare(b.numberKey)).slice(0, MAX_SURPRISES);
}
